Here's a custom React hook for handling local storage:

```javascript
import { useState, useCallback } from 'react';

function useLocalStorage(key, initialValue) {
    // Lazy initializer: read from localStorage on first render
    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            return item !== null ? JSON.parse(item) : initialValue;
        } catch (error) {
            console.warn('Error reading localStorage key "' + key + '":', error);
            return initialValue;
        }
    });

    const setValue = useCallback((value) => {
        try {
            // Allow value to be a function like useState
            const valueToStore = value instanceof Function ? value(storedValue) : value;
            setStoredValue(valueToStore);
            window.localStorage.setItem(key, JSON.stringify(valueToStore));
        } catch (error) {
            console.warn('Error setting localStorage key "' + key + '":', error);
        }
    }, [key, storedValue]);

    const remove = useCallback(() => {
        try {
            window.localStorage.removeItem(key);
            setStoredValue(initialValue);
        } catch (error) {
            console.warn('Error removing localStorage key "' + key + '":', error);
        }
    }, [key, initialValue]);

    return [storedValue, setValue, remove];
}

export default useLocalStorage;

// Usage:
// const [theme, setTheme] = useLocalStorage('theme', 'light');
// const [user, setUser, removeUser] = useLocalStorage('user', null);
```

This hook provides a state variable that is synchronized with localStorage. It handles JSON serialization/deserialization, error handling for private browsing mode, and supports functional updates like `setState`. The third return value `remove` allows clearing the stored value.
